@IsTest private class FieldFallback62 {
 @IsTest static void capture() {
 User actor=[SELECT Id FROM User WHERE LastName='FieldFallbackProbe' LIMIT 1];
 System.runAs(actor) {
Map<String,Object> observed=new Map<String,Object>();
Schema.DescribeSObjectResult objectInfo=FallbackProbe__c.SObjectType.getDescribe();
observed.put('object',new List<Boolean>{objectInfo.isAccessible(),objectInfo.isCreateable(),objectInfo.isUpdateable(),objectInfo.isDeletable()});
Map<String,Schema.SObjectField> fields=objectInfo.fields.getMap();
for(String fieldName:new List<String>{'UnlistedField__c','GrantedField__c','DeniedField__c','RecordTypeId','RequiredChoice__c'}) {
 Schema.DescribeFieldResult info=fields.get(fieldName).getDescribe();
 observed.put(fieldName,new List<Boolean>{info.isAccessible(),info.isCreateable(),info.isUpdateable(),info.isPermissionable(),info.isNillable(),info.isDefaultedOnCreate()});
}
Map<String,Object> recordTypes=new Map<String,Object>();
for(Schema.RecordTypeInfo recordType:objectInfo.getRecordTypeInfos()) {
 recordTypes.put(recordType.getDeveloperName(),new List<Boolean>{recordType.isAvailable(),recordType.isDefaultRecordTypeMapping(),recordType.isMaster()});
}
observed.put('recordTypes',recordTypes);
Map<String,Id> recordTypeIds=new Map<String,Id>();
for(Schema.RecordTypeInfo rt:objectInfo.getRecordTypeInfos()) { recordTypeIds.put(rt.getDeveloperName(),rt.getRecordTypeId()); }
observed.put('recordTypeIds',recordTypeIds);
System.assert(false,'UF|'+JSON.serialize(observed));
 }
 }
}

